<script setup lang="ts">
import { actionLabels, displayDate } from '../../labels';
import { useForm, Link } from '@inertiajs/vue3'; import BaseLayout from '../../layouts/BaseLayout.vue'; import BaseCard from '../../components/BaseCard.vue'; import FormButton from '../../components/FormButton.vue';
const props = defineProps<{ entries: { data: { id: number; actor_id: string | null; action: string; occurred_at: string; details: string }[]; prev_page_url: string | null; next_page_url: string | null }; actors: { id: string; name: string }[]; actions: string[]; filters: { actor?: string; action?: string; date?: string } }>(); const form = useForm({ actor: props.filters.actor || '', action: props.filters.action || '', date: props.filters.date || '' });
</script>
